  "  kind: \"file\";",
  "  label: string;",
  "  mediaType: string;",
  "  name: string;",
  "  origin: \"agent\" | \"provider\";",
  "  sha256?: string;",
  "  size: number;",
  "  truncated?: {",
  "    shownBytes: number;",
  "    totalBytes: number;",
  "  };",
  "} | {",
  "  kind: \"inline\";",
  "  label: string;",
  "  truncated?: {",
  "    shownBytes: number;",
  "    totalBytes: number;",
  "  };",
  "  value: string;",
  "} | {",
  "  kind: \"json\";",
  "  label: string;",
  "  truncated?: {",
  "    shownBytes: number;",
  "    totalBytes: number;",
  "  };",
  "  value: string;",
  "} | {",
  "  kind: \"text\";",
  "  label: string;",
