  "    id?: string;",
  "    noun?: string;",
  "    plural?: string;",
  "  };",
  "};",
  "",
  "export type AdminFormatPatch = {",
  "  agentHint?: string;",
  "  enabled?: boolean;",
  "  overrides?: {",
  "    icon?: \"appWindow\" | \"chartBar\" | \"fileText\" | \"flowArrow\" | \"gridNine\" | \"kanban\" | \"listChecks\" | \"notebook\" | \"presentation\" | \"table\" | null;",
